import 'package:firebase_core/firebase_core.dart';
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

import 'config.dart';
// Generated by `flutterfire configure` — see README.
import 'firebase_options.dart';
import 'ui/pages/role_gate.dart';
import 'ui/theme.dart';

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  await Firebase.initializeApp(options: DefaultFirebaseOptions.currentPlatform);
  runApp(const ProviderScope(child: ShopLiteApp()));
}

class ShopLiteApp extends StatelessWidget {
  const ShopLiteApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: appName,
      debugShowCheckedModeBanner: false,
      theme: buildAppTheme(),
      // Browsing is open to everyone; sign-in is asked for only at checkout,
      // for "My orders" and to open a shop (see ensureSignedIn). Signed-in
      // shop admins and the super admin get their own screens instead.
      home: const RoleGate(),
    );
  }
}
